import numpy as np

class FLSecurity:
    def __init__(self, num_clients, malicious_ratio=0.2):
        self.num_clients = num_clients
        self.num_malicious = int(num_clients * malicious_ratio)
    def data_poison(self, data, flip_ratio=0.3):
        X, y = data
        n_flip = int(len(y) * flip_ratio)
        flip_idx = np.random.choice(len(y), n_flip, replace=False)
        poisoned_y = y.copy()
        poisoned_y[flip_idx] = (poisoned_y[flip_idx] + 1) % 10
        return X, poisoned_y
    def model_poison(self, clean_update, attack_strength=10.0):
        return {k: -attack_strength * v for k, v in clean_update.items()}
    def krum_aggregate(self, client_updates, num_malicious):
        n = len(client_updates)
        f = num_malicious
        flat = [np.concatenate([v.flatten() for v in w.values()]) for w in client_updates]
        dists = np.zeros((n, n))
        for i in range(n):
            for j in range(i+1, n):
                d = np.linalg.norm(flat[i] - flat[j])
                dists[i, j] = dists[j, i] = d
        scores = np.zeros(n)
        for i in range(n):
            sorted_d = np.sort(dists[i])
            scores[i] = np.sum(sorted_d[1:n-f-1])
        best = np.argmin(scores)
        return client_updates[best]
    def detect_outliers(self, client_updates, threshold=2.0):
        flat = [np.concatenate([v.flatten() for v in w.values()]) for w in client_updates]
        mean_update = np.mean(flat, axis=0)
        honest = []
        for i, f in enumerate(flat):
            cos_sim = np.dot(f, mean_update) / (np.linalg.norm(f) * np.linalg.norm(mean_update) + 1e-8)
            if cos_sim > threshold / 10:
                honest.append(i)
        return honest
